// Usage Instructions
// ═══════════════════════════════════════════════════════════════════════════
//
// Option 1: Use GESTURE_CONSTANTS object directly in code
//   import { GESTURE_CONSTANTS } from './generatedGestures';
//   const waving = GESTURE_CONSTANTS.WAVING;
//
// Option 2: Copy individual constants to VRMSkeletonManager.tsx
//   - Scroll up to find the gesture constants block
//   - Copy the const declarations (e.g., WAVING_RUA_X, WAVING_RUA_Y, ...)
//   - Paste into VRMSkeletonManager.tsx gesture constants section
//   - Add a case in the gesture switch statement to use these values
//
// Option 3: Fine-tune with GestureCalibrator
//   - Load the gesture in the app
//   - Open GestureCalibrator UI
